const DELTA_MENU_SOUNDS=["", "", "", "", "", "", "", "", "", ""];
(function(){
 const KEY='delta-rpg-sound-v1';
 let enabled=false,unlocked=false,lastHover=0,lastSelect=0,hoverIndex=0,selectIndex=0;
 try{enabled=localStorage.getItem(KEY)==='true'}catch(_){}
 const btn=document.getElementById('soundToggle');
 function repaint(){if(!btn)return;btn.textContent=enabled?'♫ SONS: ON':'♫ SONS: OFF';btn.setAttribute('aria-pressed',String(enabled))}
 function play(select){
  if(!enabled||!unlocked||document.hidden)return;
  const now=performance.now();
  if(select){if(now-lastSelect<130)return;lastSelect=now}
  else{if(now-lastHover<170)return;lastHover=now}
  const ids=select?[5,6,7,8,9,3]:[0,1,2,4,3,0,2];
  const n=select?selectIndex++:hoverIndex++;
  const audio=new Audio('data:audio/mpeg;base64,'+DELTA_MENU_SOUNDS[ids[n%ids.length]]);
  audio.volume=select?.38:.16;
  audio.play().catch(()=>{});
 }
 if(btn){btn.addEventListener('click',()=>{enabled=!enabled;unlocked=true;try{localStorage.setItem(KEY,String(enabled))}catch(_){}repaint();if(enabled)play(true)});repaint()}
 document.addEventListener('pointerover',e=>{
  const target=e.target.closest?.('button,.file-card,.entry-row,.theme-option,.theme-scene-btn');
  if(target&&!target.contains(e.relatedTarget))play(false)
 },{passive:true});
 document.addEventListener('click',e=>{
  unlocked=true;
  if(e.target.closest?.('button,.file-card,.entry-row,.theme-option,.theme-scene-btn')&&!e.target.closest('#soundToggle'))play(true);
 },true);
})();
